// TypeScript Version: 4.1

/* eslint-disable max-lines */

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';

/**
* Legend direction.
*/
type Direction = 'horizontal' | 'vertical';

/**
* Format type.
*/
type FormatType = 'number' | 'time' | 'utc';

/**
* Grid alignment.
*/
type GridAlignment = 'all' | 'each' | 'none';

/**
* Text alignment.
*/
type TextAlignment = 'left' | 'right' | 'center';

/**
* Vertical baseline.
*/
type VerticalBaseline = 'alphabetic' | 'top' | 'middle' | 'bottom' | 'line-top' | 'line-bottom';

/**
* Font style.
*/
type FontStyle = 'normal' | 'italic' | 'oblique';

/**
* Font weight.
*/
type FontWeight = 'normal' | 'bold' | 'lighter' | 'bolder' | '100' | '200' | '300' | '400' | '500' | '600' | '700' | '800' | '900' | number;

/**
* Strategy for resolving overlapping legend labels.
*/
type LabelOverlapStrategy = 'parity' | 'greedy';

/**
* Legend orientation.
*/
type Orientation = 'bottom' | 'bottom-left' | 'bottom-right' | 'left' | 'none' | 'right' | 'top' | 'top-left' | 'top-right';

/**
* Symbol shape.
*/
type SymbolShape = 'arrow' | 'circle' | 'cross' | 'diamond' | 'square' | 'stroke' | 'triangle' | 'triangle-down' | 'triangle-left' | 'triangle-right' | 'triangle-up' | 'wedge';

/**
* Anchor position.
*/
type AnchorPosition = 'start' | 'middle' | 'end';

/**
* Legend title orientation.
*/
type TitleOrientation = 'left' | 'right' | 'top' | 'bottom';

/**
* Legend type.
*/
type Type = 'discrete' | 'gradient' | 'symbol';

/**
* Interface describing constructor options.
*/
interface Options {
	/**
	* Boolean indicating whether ARIA attributes should be included in SVG output. Default: true.
	*/
	aria?: boolean;

	/**
	* Height (in pixels) to clip symbol legend entries and limit their size.
	*/
	clipHeight?: number;

	/**
	* Horizontal padding (in pixels) between symbol legend columns.
	*/
	columnPadding?: number;

	/**
	* Number of columns in which to arrange symbol legend entries.
	*/
	columns?: number;

	/**
	* Corner radius for the full legend.
	*/
	cornerRadius?: number;

	/**
	* Legend description. Default: ''.
	*/
	description?: string;

	/**
	* Direction of the legend. Default: 'vertical'.
	*/
	direction?: Direction;

	/**
	* Mark encodings for custom legend styling.
	*/
	encode?: any;

	/**
	* Name of the scale that maps to a fill color.
	*/
	fill?: string;

	/**
	* Background fill color for the full legend.
	*/
	fillColor?: string;

	/**
	* Format specifier for legend labels.
	*/
	format?: string | Record<string, unknown>;

	/**
	* Type of format to use for legend scales which do not have a strict domain data type.
	*/
	formatType?: FormatType;

	/**
	* Length (in pixels) of the primary axis of a color gradient.
	*/
	gradientLength?: number;

	/**
	* Opacity of the color gradient.
	*/
	gradientOpacity?: number;

	/**
	* Stroke color of the color gradient border.
	*/
	gradientStrokeColor?: string;

	/**
	* Stroke width of the color gradient border.
	*/
	gradientStrokeWidth?: number;

	/**
	* Thickness (in pixels) of the color gradient.
	*/
	gradientThickness?: number;

	/**
	* Grid alignment for legend entries. Default: 'each'.
	*/
	gridAlign?: GridAlignment;

	/**
	* Horizontal text alignment of legend labels.
	*/
	labelAlign?: TextAlignment;

	/**
	* Vertical text baseline of legend labels.
	*/
	labelBaseline?: VerticalBaseline;

	/**
	* Text color for legend labels.
	*/
	labelColor?: string;

	/**
	* Font name for legend labels.
	*/
	labelFont?: string;

	/**
	* Font size (in pixels) of legend labels.
	*/
	labelFontSize?: number;

	/**
	* Font style of legend labels.
	*/
	labelFontStyle?: FontStyle;

	/**
	* Font weight of legend labels.
	*/
	labelFontWeight?: FontWeight;

	/**
	* Maximum allowed length (in pixels) of legend labels.
	*/
	labelLimit?: number;

	/**
	* Offset (in pixels) between legend labels and their corresponding symbol or gradient.
	*/
	labelOffset?: number;

	/**
	* Opacity of legend labels.
	*/
	labelOpacity?: number;

	/**
	* Strategy for resolving overlapping legend labels in gradient legends. Default: true.
	*/
	labelOverlap?: boolean | LabelOverlapStrategy;

	/**
	* Minimum separation between legend label bounding boxes for them to be considered non-overlapping. Default: 0.
	*/
	labelSeparation?: number;

	/**
	* Custom `x` position (in pixels) for the legend group.
	*/
	legendX?: number;

	/**
	* Custom `y` position (in pixels) for the legend group.
	*/
	legendY?: number;

	/**
	* Offset (in pixels) by which to displace the legend from the data rectangle and axes.
	*/
	offset?: number | Record<string, unknown>;

	/**
	* Name of the scale that maps to an opacity value.
	*/
	opacity?: string;

	/**
	* Legend orientation. Default: 'right'.
	*/
	orient?: Orientation;

	/**
	* Padding (in pixels) between legend border and content of the legend group.
	*/
	padding?: number | Record<string, unknown>;

	/**
	* Vertical padding (in pixels) between symbol legend entries.
	*/
	rowPadding?: number;

	/**
	* Name of the scale that maps to a shape value.
	*/
	shape?: string;

	/**
	* Name of the scale that maps to a size value.
	*/
	size?: string;

	/**
	* Name of the scale that maps to a stroke color.
	*/
	stroke?: string;

	/**
	* Border stroke color for the full legend.
	*/
	strokeColor?: string;

	/**
	* Name of the scale that maps to a stroke dash value.
	*/
	strokeDash?: string;

	/**
	* Name of the scale that maps to a stroke width value.
	*/
	strokeWidth?: string;

	/**
	* Stroke dash for symbol outlines. Default: [].
	*/
	symbolDash?: Array<number>;

	/**
	* Pixel offset at which to start the symbol stroke dash array.
	*/
	symbolDashOffset?: number;

	/**
	* Fill color of legend symbols.
	*/
	symbolFillColor?: string;

	/**
	* Maximum number of entries for a symbol legend.
	*/
	symbolLimit?: number;

	/**
	* Horizontal pixel offset for legend symbols.
	*/
	symbolOffset?: number;

	/**
	* Opacity of legend symbols.
	*/
	symbolOpacity?: number;

	/**
	* Default symbol area size (in squared pixels).
	*/
	symbolSize?: number;

	/**
	* Stroke color of legend symbols.
	*/
	symbolStrokeColor?: string;

	/**
	* Default stroke width of legend symbols.
	*/
	symbolStrokeWidth?: number;

	/**
	* Default symbol shape type for legend entries.
	*/
	symbolType?: SymbolShape;

	/**
	* Desired number of tick values for quantitative legends.
	*/
	tickCount?: number | string | Record<string, unknown>;

	/**
	* Minimum desired step between tick values (in the same units as scale domain values).
	*/
	tickMinStep?: number;

	/**
	* Legend title.
	*/
	title?: string | Array<string>;

	/**
	* Horizontal text alignment of the legend title.
	*/
	titleAlign?: TextAlignment;

	/**
	* Legend title anchor position. Default: null.
	*/
	titleAnchor?: AnchorPosition | null;

	/**
	* Vertical text baseline of the legend title.
	*/
	titleBaseline?: VerticalBaseline;

	/**
	* Text color of the legend title.
	*/
	titleColor?: string;

	/**
	* Font name of the legend title.
	*/
	titleFont?: string;

	/**
	* Font size of the legend title.
	*/
	titleFontSize?: number;

	/**
	* Font style of the legend title.
	*/
	titleFontStyle?: FontStyle;

	/**
	* Font weight of the legend title.
	*/
	titleFontWeight?: FontWeight;

	/**
	* Maximum allowed length (in pixels) of the legend title.
	*/
	titleLimit?: number;

	/**
	* Line height (in pixels) for multi-line title text.
	*/
	titleLineHeight?: number;

	/**
	* Opacity of the legend title.
	*/
	titleOpacity?: number;

	/**
	* Orientation of the legend title. Default: 'top'.
	*/
	titleOrient?: TitleOrientation;

	/**
	* Padding (in pixels) between the legend title and entries.
	*/
	titlePadding?: number | Record<string, unknown>;

	/**
	* Legend type.
	*/
	type?: Type;

	/**
	* Explicit set of legend values.
	*/
	values?: Collection;

	/**
	* Integer z-index indicating the layering of the legend group relative to other axis, mark, and legend groups. Default: 0.
	*/
	zindex?: number;
}

/**
* Interface describing a JSON-serialized legend instance.
*/
